def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Prim's algorithm
    visited = [False] * n
    min_heap = [(0, 0)]  # (cost, city)
    total_cost = 0

    while min_heap:
        cost, city = heapq.heappop(min_heap)
        if visited[city]:
            continue
        visited[city] = True
        total_cost += cost
        for neighbor, weight in graph[city]:
            if not visited[neighbor]:
                heapq.heappush(min_heap, (weight, neighbor))

    if False in visited:
        return -1
    return total_cost

